import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.CXbMDk3A.js";var i=JSON.parse(`{"title":"Recon-Owned Incarnation-Bound Native Loader","description":"","frontmatter":{"id":"decision.0003","title":"Recon-Owned Incarnation-Bound Native Loader","status":"accepted","established-by":"proposal.0005","supersedes":[]},"headers":[],"relativePath":"decisions/0003-recon-owned-native-loader.md","filePath":"decisions/0003-recon-owned-native-loader.md"}`),a={name:`decisions/0003-recon-owned-native-loader.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="recon-owned-incarnation-bound-native-loader" tabindex="-1">Recon-Owned Incarnation-Bound Native Loader <a class="header-anchor" href="#recon-owned-incarnation-bound-native-loader" aria-label="Permalink to “Recon-Owned Incarnation-Bound Native Loader”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>Recon uses its own universal C loader and matching helper for native macOS inspection. The loader verifies the selected process incarnation before every target-side effect, and the helper exposes only authenticated, bounded inspection operations.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Native AppKit inspection requires target-side execution on the application&#39;s main thread. A debugger or general-purpose injection framework would add a broad runtime and a second security model. A PID alone is not a process identity: it can be reused between selection and injection. Apple-silicon targets also require both arm64 and arm64e support, pointer-authentication-aware thread setup, and an honest research-host boundary for protected applications. Prior art supplied useful mechanisms, but not Recon&#39;s identity, lifecycle, or delivery guarantees.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Build <code>recon-loader</code> for arm64 and arm64e, with Recon&#39;s own debugger and thread-state entitlements. It acquires a task control port, verifies the audit token&#39;s PID and pidversion, checks dyld shared-cache agreement, and revalidates that incarnation before allocation and again before starting the injected thread. Its bootstrap enters only <code>recon_helper_main</code> in the matching Recon helper.</p><p>The helper uses an owner-private local socket, kernel peer audit tokens, per-session capabilities, and a versioned, size-bounded protocol. It supports closed inspection operations rather than arbitrary code evaluation. Helper build mismatches fail instead of triggering replacement or downgrade. First-party and other non-cooperative targets require the separately prepared research profile; the loader never weakens host or target protections as an inspection side effect.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><p>Owning this narrow path makes the pre-effect identity guarantee, arm64e behavior, protocol bounds, and cleanup semantics directly testable. A C loader avoids the unsupported arm64e Rust runtime failure observed during implementation. A closed helper keeps the privileged target-side surface smaller than a general debugger or scripting endpoint. Explicit build and host checks preserve the distinction between cooperative inspection and an operator-weakened research machine.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li>Frida or another maintained injection framework — rejected by the project owner; it would introduce a second runtime and trust model rather than Recon-owned identity and protocol guarantees.</li><li>A Rust-only loader — simpler integration, but the arm64e standard-library initialization crashed before <code>main</code> on the supported toolchain, so it could not meet the required target matrix.</li><li>Cooperative embedding only — avoids protected-target complexity but excludes the required research-machine outcome.</li><li>Unchecked PID-based injection or a general debugging endpoint — easier to implement, but cannot prevent effects on a replacement process and unnecessarily expands target-side authority.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="good" tabindex="-1">Good <a class="header-anchor" href="#good" aria-label="Permalink to “Good”">​</a></h3><ul><li>Every target-side effect is tied to a kernel-verified process incarnation.</li><li>One loader/helper pair covers arm64 and arm64e with explicit PAC handling and repeatable fixture tests.</li><li>Resident code, session access, helper build compatibility, and host preparation remain separate, observable concepts.</li><li>The target-side API stays bounded to Recon&#39;s inspection operations.</li></ul><h3 id="bad" tabindex="-1">Bad <a class="header-anchor" href="#bad" aria-label="Permalink to “Bad”">​</a></h3><ul><li>Recon owns Mach, dyld, pointer-authentication, and macOS-version compatibility maintenance.</li><li>Closing a session cannot safely unload the helper; full replacement requires target restart.</li><li>First-party inspection requires an explicitly weakened research host and is not a stock-machine capability.</li><li>Packaging must keep the CLI, loader, helper, and build identity together.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Proposal</th></tr></thead><tbody><tr><td>2026-10-28</td><td>Accepted the Recon-owned, incarnation-bound loader and closed helper protocol.</td><td>proposal.0005</td></tr></tbody></table>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};